script:
# ─────────────────────────────────────────────────────────────────────────────
# Frappe Server Script – fetchQualityRawData (PivotTable.js / Full Pivot)
# Type: API
# API Method: fetchQualityRawData
#
# Returns ALL quality parameters from QC Parameters doctype as columns
# Removed "Period" - only using "Week"
#
# Performance: records and defect counts are fetched with two plain queries
# (no 60-column CASE pivot), dates are filtered sargably on `creation`, filter
# options are cached for 5 minutes. With compact=1 the page gets a
# dictionary-encoded, sparse payload (defect columns only where they have data);
# without it the original row-object shape is returned unchanged.
# ─────────────────────────────────────────────────────────────────────────────

try:
    # ── Parse incoming filters ──────────────────────────────────────────────
    year        = frappe.form_dict.get("year", "")
    farm        = frappe.form_dict.get("farm", "")
    week        = frappe.form_dict.get("week", "")
    variety     = frappe.form_dict.get("variety", "")
    greenhouse  = frappe.form_dict.get("greenhouse", "")
    from_date   = frappe.form_dict.get("from_date", "")
    to_date     = frappe.form_dict.get("to_date", "")
    compact     = frappe.form_dict.get("compact", "")

    # ── Build WHERE clause on the indexed 'creation' field (sargable) ───────
    conditions = ["qr.docstatus < 2", "qr.control_point = 'Intake'"]
    values = {}

    if year:
        conditions.append("qr.creation >= MAKEDATE(%(year)s, 1) AND qr.creation < MAKEDATE(%(year)s + 1, 1)")
        values["year"] = int(year)

    # Farm/Variety/GH are multi-selects on the page (CSV) -> IN
    def in_list(v):
        return ", ".join([frappe.db.escape(x.strip()) for x in str(v).split(",") if x.strip()])

    if farm:
        conditions.append("qr.farm IN (" + in_list(farm) + ")")

    if week:
        conditions.append("WEEK(qr.creation, 1) = %(week)s")
        values["week"] = int(week)

    if variety:
        conditions.append("qr.variety IN (" + in_list(variety) + ")")

    if greenhouse:
        conditions.append("qr.ghouse IN (" + in_list(greenhouse) + ")")

    if from_date:
        conditions.append("qr.creation >= DATE(%(from_date)s)")
        values["from_date"] = from_date

    if to_date:
        conditions.append("qr.creation < DATE_ADD(DATE(%(to_date)s), INTERVAL 1 DAY)")
        values["to_date"] = to_date

    where_clause = " AND ".join(conditions)

    # ── 1. Parameter names from the QC Parameters doctype ───────────────────
    all_param_rows = frappe.db.sql(
        "SELECT DISTINCT parameter FROM `tabQC Parameters`"
        " WHERE parameter IS NOT NULL AND parameter != '' ORDER BY parameter",
        as_dict=1
    )
    all_param_names = [row.parameter for row in all_param_rows]
    param_idx = {}
    for i, pn in enumerate(all_param_names):
        param_idx[pn.lower()] = i

    # ── 2. Records (one row each, no join) ──────────────────────────────────
    raw_data = frappe.db.sql(
        "SELECT qr.name, qr.farm, qr.ghouse,"
        " YEAR(qr.creation),"
        " CONCAT('W', LPAD(WEEK(qr.creation, 1), 2, '0')),"
        " DATE(qr.creation), qr.variety, qr.control_action,"
        " qr.stems_received, qr.stems_checked, qr.quarantined_stems"
        " FROM `tabQuality Reporting` qr"
        " WHERE " + where_clause +
        " ORDER BY qr.creation DESC",
        values, as_list=1
    )

    # ── 3. Defect counts: only the (record, parameter) pairs that exist ─────
    defect_rows = frappe.db.sql(
        "SELECT qp.parent, qp.parameter_name, SUM(qp.`count`)"
        " FROM `tabQuality Parameter` qp"
        " INNER JOIN `tabQuality Reporting` qr ON qp.parent = qr.name"
        " WHERE qp.parenttype = 'Quality Reporting' AND " + where_clause +
        " GROUP BY qp.parent, qp.parameter_name",
        values, as_list=1
    )
    defects = {}
    for parent, pname, cnt in defect_rows:
        if pname is None:
            continue
        pi = param_idx.get(str(pname).lower())
        if pi is None:
            continue
        cur = defects.get(parent)
        if cur is None:
            cur = {}
            defects[parent] = cur
        cur[pi] = cur.get(pi, 0) + (int(cnt) if cnt else 0)

    # ── 4. Shape the rows ───────────────────────────────────────────────────
    rows_out = []
    if compact:
        # dictionary-encode the repeated strings: one code table per column
        fm = {}
        gm = {}
        vm = {}
        am = {}
        dm_ = {}
        wm = {}
        for name, f, g, yr, wk, dt, v, a, rc, ck, qn in raw_data:
            if f not in fm:
                fm[f] = len(fm)
            if g not in gm:
                gm[g] = len(gm)
            if v not in vm:
                vm[v] = len(vm)
            if a not in am:
                am[a] = len(am)
            if dt not in dm_:
                dm_[dt] = len(dm_)
            if wk not in wm:
                wm[wk] = len(wm)
        for name, f, g, yr, wk, dt, v, a, rc, ck, qn in raw_data:
            flat = []
            dm = defects.get(name)
            if dm:
                for pi in sorted(dm.keys()):
                    if dm[pi]:
                        flat.append(pi)
                        flat.append(dm[pi])
            rows_out.append([fm[f], gm[g], dm_[dt], wm[wk], vm[v], am[a],
                             int(rc) if rc else 0, int(ck) if ck else 0, int(qn) if qn else 0, flat])

        def keys_in_order(m):
            out = [""] * len(m)
            for k in m:
                out[m[k]] = k if k else ""
            return out

        dicts = {
            "farm": keys_in_order(fm), "gh": keys_in_order(gm), "variety": keys_in_order(vm),
            "action": keys_in_order(am), "date": [str(x).split(" ")[0] if x else "" for x in keys_in_order(dm_)],
            "week": keys_in_order(wm),
        }
    else:
        zero_params = {}
        for pn in all_param_names:
            zero_params[pn] = 0
        for name, f, g, yr, wk, dt, v, a, rc, ck, qn in raw_data:
            clean_row = dict(zero_params)
            clean_row["Farm"] = f or ""
            clean_row["GH"] = g or ""
            clean_row["Year"] = int(yr) if yr else 0
            clean_row["Week"] = wk or ""
            clean_row["Date"] = str(dt).split(" ")[0] if dt else ""
            clean_row["Variety"] = v or ""
            clean_row["Action"] = a or ""
            clean_row["Stems Received"] = int(rc) if rc else 0
            clean_row["Stems Checked"] = int(ck) if ck else 0
            clean_row["Quarantined Stems"] = int(qn) if qn else 0
            dm = defects.get(name)
            if dm:
                for pi in dm:
                    clean_row[all_param_names[pi]] = dm[pi]
            rows_out.append(clean_row)

    # ── 5. Filter options (cached 5 min; they only change when records land) ─
    filter_options = None
    cache_key = "qrd_filter_options_v2"
    try:
        filter_options = frappe.cache().get_value(cache_key)
    except Exception:
        filter_options = None

    if not filter_options:
        base = "FROM `tabQuality Reporting` WHERE docstatus < 2 AND control_point = 'Intake'"
        filter_options = {}
        filter_options["years"] = [r.yr for r in frappe.db.sql(
            "SELECT DISTINCT YEAR(creation) AS yr " + base + " ORDER BY yr DESC", as_dict=1)]
        filter_options["farms"] = [r.farm for r in frappe.db.sql(
            "SELECT DISTINCT farm " + base + " AND farm IS NOT NULL AND farm != '' ORDER BY farm", as_dict=1)]
        filter_options["varieties"] = [r.variety for r in frappe.db.sql(
            "SELECT DISTINCT variety " + base + " AND variety IS NOT NULL AND variety != '' ORDER BY variety", as_dict=1)]
        filter_options["greenhouses"] = [r.ghouse for r in frappe.db.sql(
            "SELECT DISTINCT ghouse " + base + " AND ghouse IS NOT NULL AND ghouse != '' ORDER BY ghouse", as_dict=1)]
        filter_options["weeks"] = [r.wk for r in frappe.db.sql(
            "SELECT DISTINCT WEEK(creation, 1) AS wk " + base + " ORDER BY wk", as_dict=1)]
        try:
            frappe.cache().set_value(cache_key, filter_options, expires_in_sec=300)
        except Exception:
            pass

    # ── Return ──────────────────────────────────────────────────────────────
    out = {
        "success": True,
        "data": rows_out,
        "param_names": all_param_names,
        "record_count": len(rows_out),
        "filter_options": filter_options
    }
    if compact:
        out["compact"] = 1
        out["dict"] = dicts
    frappe.response["message"] = out

except Exception as e:
    frappe.log_error("fetchQualityRawData Error", e)
    frappe.response["message"] = {
        "success": False,
        "error": str(e)
    }
